public void pay(String paymentType, String securityCode) {
    PaymentProcessor processor = new PaymentProcessor();
    if (processor.processPayment(paymentType, securityCode)) {
        this.status = "paid";
    } else {
        this.status = "failed";
    }
}

class PaymentProcessor {
    public boolean processPayment(String paymentType, String securityCode) {
        switch (paymentType.toLowerCase()) {
            case "debit":
                System.out.println("Processing debit payment type");
                System.out.println("Verifying security code: " + securityCode);
                return true;

            case "credit":
                System.out.println("Processing credit payment type");
                System.out.println("Verifying security code: " + securityCode);
                return true;

            default:
                throw new IllegalArgumentException("Unknown payment type: " + paymentType);
        }
    }
}
